-- 2.4. Proyectos (sin-piedad, sin-tiempo-peiko, y-el-ano-que-viene-que)
with d as (select $datos$[{"slug":"sin-piedad","id_antiguo":"sin-piedad","titulo":"Sin Piedad","tipo":"cortometraje","servicios":["direccion-de-fotografia"],"anio":null,"direccion":"Ángela Manzano","productora":"Proyecto personal de Ángela Manzano","papel":"Dirección de fotografía","camara":"","premios":[],"tarjeta":"Un hombre machacado por su trabajo decide secuestrar a su jefa.","historia":"Ángela Manzano lo cuenta desde dentro de su cabeza, con tono onírico. Mi trabajo fue traducir ese estado mental a luz y composición. Aún no es público: se prepara para festivales, por eso aquí solo hay fotogramas.","como_lo_hicimos":"- **Oficina como limbo.** Luz uniforme y fría sobre el blanco.\n- **Confrontación.** Prácticas cálidas que fingen normalidad, con sombras profundas sobre él.\n- **Prisión mental.** Sombras de persiana y tonos azulados, sin paredes.\n- **Secuestro.** Contraluz intenso, como un halo teatral.","el_reto":"Rodamos casi todo sobre un ciclorama blanco. Había que convertir un solo espacio neutro en varios lugares, cada uno con su carga emocional.","el_resultado":"","frase":"Una cárcel hecha *solo de luz*.","titulos_seccion":{"historia":"El proyecto","como_lo_hicimos":"Decisiones clave","el_reto":"El reto","el_resultado":"Resultado"},"youtube_id":null,"youtube_inicio":null,"videos":[],"videos_debajo_del_texto":false,"poster":"https://i.imgur.com/j3loxUV.png","galeria":["https://i.imgur.com/j3loxUV.png","https://i.ibb.co/Z6sq4zns/3a45388c-c86c-4c6c-a65e-08ecc09924d4.jpg","https://i.ibb.co/8LbdJj5g/adfb7bc1-79ad-49fb-9085-05ed6ad25614.jpg","https://i.ibb.co/LX70LVX2/7858818b-410d-4e0e-b79d-2f325f66c072.jpg"],"destacado_orden":null,"orden":10},{"slug":"sin-tiempo-peiko","id_antiguo":"sin-tiempo-peiko","titulo":"Sin Tiempo, Peiko","tipo":"videoclip","servicios":["filmmaker","direccion-de-fotografia","edicion"],"anio":null,"direccion":"Josep Mira Lozano","productora":"Proyecto de estudios","papel":"Dirección y fotografía","camara":"Canon C200 · 50 mm","premios":[],"tarjeta":"Una canción sobre el paso del tiempo y la distancia entre el éxito y el fracaso, contada como un drama.","historia":"Peiko canta y, a la vez, vive la caída de su personaje. Pasé la canción a un plan de rodaje: cada movimiento de cámara y cada óptica acompañan ese arco.","como_lo_hicimos":"- **Dos casas opuestas.** Una moderna y lujosa, otra podrida: dos atmósferas para la fractura del personaje.\n- **Final en una celda.** La luz se enfría y Peiko termina cantando agarrado a los barrotes.","el_reto":"Que la caída se viera en la imagen y no solo en la letra.","el_resultado":"","frase":"Del lujo a *los barrotes*, al ritmo de una canción.","titulos_seccion":{"historia":"El proyecto","como_lo_hicimos":"Decisiones clave","el_reto":"El reto","el_resultado":"Resultado"},"youtube_id":"wCnVb2o-k7Y","youtube_inicio":null,"videos":[],"videos_debajo_del_texto":false,"poster":"https://i.imgur.com/uUiXiQT.png","galeria":["https://i.imgur.com/uUiXiQT.png","https://i.ibb.co/MDqyCBQ1/Captura-de-pantalla-2026-05-12-193744.png","https://i.ibb.co/Df7JzTry/Captura-de-pantalla-2026-05-12-193832.png","https://i.ibb.co/q30FzfyN/Captura-de-pantalla-2026-05-12-193908.png","https://i.ibb.co/7JDnD0s9/Captura-de-pantalla-2026-05-12-194115.png"],"destacado_orden":null,"orden":8},{"slug":"y-el-ano-que-viene-que","id_antiguo":"y-el-ano-que-viene-que","titulo":"Y el año que viene, ¿qué?","tipo":"cortometraje","servicios":["direccion-de-fotografia","filmmaker","edicion"],"anio":2024,"direccion":"Josep Mira Lozano","productora":"Proyecto propio · ESCAC Dreammakers, Cupra","papel":"Guion, dirección, fotografía y montaje","camara":"Sony FX3 · Tamron","premios":[{"anio":2024,"nombre":"Podio","tipo":"podio","festival":"ESCAC Dreammakers Contest"}],"tarjeta":"El ESCAC Dreammakers Contest de Cupra pedía un corto con tres palabras obligatorias: *Ojo*, *Cine* y *Barcelona*.","historia":"Las uní de la única forma que me parecía honesta, contando mi propia relación con el cine. Es un relato autobiográfico en voz en off, y también me puse delante de la cámara. Me ayudaron Adrià Mira Lozano y Lara Ruiz Martín.","como_lo_hicimos":"- **La voz primero.** Escribí la narración antes que nada, con *Amélie* como referencia: cálida y cercana.\n- **Contraste de ritmos.** Un montaje acelerado contra una voz tranquila. De ahí sale la energía.","el_reto":"El plazo real fue de unos 15 días para idear, rodar, montar y entregar. Lo resolví quedándome solo con lo que contaba la historia.","el_resultado":"- Podio del ESCAC Dreammakers Contest 2024.\n- Acceso a becas de la ESCAC.","frase":"Un concurso me pidió tres palabras. Le respondí con *mi historia*.","titulos_seccion":{"historia":"El proyecto","como_lo_hicimos":"Decisiones clave","el_reto":"El reto","el_resultado":"Resultado"},"youtube_id":"dHp3YUb1x2I","youtube_inicio":30,"videos":[],"videos_debajo_del_texto":false,"poster":"https://i.imgur.com/ESU7wLA.jpeg","galeria":["https://i.imgur.com/ESU7wLA.jpeg","https://i.imgur.com/qtM2MCm.jpg","https://i.imgur.com/FdyOIDU.jpg"],"destacado_orden":1,"orden":1}]$datos$::jsonb as j)
insert into public.proyectos as t (
  idioma, slug, id_antiguo, titulo, tipo_id, anio, direccion, productora, papel, camara, premios,
  tarjeta, historia, como_lo_hicimos, el_reto, el_resultado, frase, titulos_seccion,
  youtube_id, youtube_inicio, videos, videos_debajo_del_texto, imagen_id, galeria, destacado_orden, orden, estado
)
select 'es', p ->> 'slug', p ->> 'id_antiguo', p ->> 'titulo',
  (select id from public.tipos_proyecto where slug = p ->> 'tipo'),
  (p ->> 'anio')::int, p ->> 'direccion', p ->> 'productora', p ->> 'papel', p ->> 'camara', p -> 'premios',
  p ->> 'tarjeta', p ->> 'historia', p ->> 'como_lo_hicimos', p ->> 'el_reto', p ->> 'el_resultado', p ->> 'frase',
  p -> 'titulos_seccion', p ->> 'youtube_id', (p ->> 'youtube_inicio')::int, p -> 'videos',
  (p ->> 'videos_debajo_del_texto')::boolean,
  (select id from public.medios where url_origen = p ->> 'poster' order by creado_en limit 1),
  coalesce((
    select jsonb_agg(jsonb_build_object('medio', m.id, 'pie', '') order by g.n)
    from jsonb_array_elements_text(p -> 'galeria') with ordinality g(url, n)
    cross join lateral (select id from public.medios where url_origen = g.url order by creado_en limit 1) m
  ), '[]'::jsonb),
  (p ->> 'destacado_orden')::int, (p ->> 'orden')::int, 'borrador'
from d, jsonb_array_elements(d.j) p
on conflict (idioma, slug) do update set
  id_antiguo = excluded.id_antiguo, titulo = excluded.titulo, tipo_id = excluded.tipo_id, anio = excluded.anio,
  direccion = excluded.direccion, productora = excluded.productora, papel = excluded.papel, camara = excluded.camara,
  premios = excluded.premios, tarjeta = excluded.tarjeta, historia = excluded.historia,
  como_lo_hicimos = excluded.como_lo_hicimos, el_reto = excluded.el_reto, el_resultado = excluded.el_resultado,
  frase = excluded.frase, titulos_seccion = excluded.titulos_seccion, youtube_id = excluded.youtube_id,
  youtube_inicio = excluded.youtube_inicio, videos = excluded.videos,
  videos_debajo_del_texto = excluded.videos_debajo_del_texto, imagen_id = excluded.imagen_id,
  galeria = excluded.galeria, destacado_orden = excluded.destacado_orden, orden = excluded.orden
where t.estado = 'borrador';

-- 3. Servicios de cada proyecto: solo enlaza los que ya existan en `servicios` (los carga la tarea S3).
-- Si S3 llega después, basta con volver a ejecutar esta sentencia.
with d as (select $datos$[{"slug":"100-baladas-arkano","servicios":["filmmaker","direccion-de-fotografia","edicion"]},{"slug":"bodas","servicios":["filmmaker","edicion"]},{"slug":"conciertos","servicios":["filmmaker","edicion"]},{"slug":"el-cirujano","servicios":["direccion-de-fotografia"]},{"slug":"el-viajero","servicios":["filmmaker","direccion-de-fotografia","edicion"]},{"slug":"ep-oscuridad-adrian-munoz","servicios":["direccion-de-fotografia"]},{"slug":"eventos-deportivos","servicios":["filmmaker","edicion"]},{"slug":"expandete-spot-juno-media","servicios":["filmmaker","edicion"]},{"slug":"kiboko","servicios":["edicion"]},{"slug":"no-se-esta-tan-mal-lovva","servicios":["direccion-de-fotografia","edicion"]},{"slug":"recreacion-el-padrino","servicios":["direccion-de-fotografia","edicion"]},{"slug":"recreacion-nosferatu","servicios":["direccion-de-fotografia","edicion"]},{"slug":"recreacion-star-wars-luke-vader","servicios":["direccion-de-fotografia","edicion"]},{"slug":"recreacion-star-wars-sin-cgi","servicios":["direccion-de-fotografia","edicion"]},{"slug":"reels-redes-sociales","servicios":["filmmaker","edicion"]},{"slug":"sin-piedad","servicios":["direccion-de-fotografia"]},{"slug":"sin-tiempo-peiko","servicios":["filmmaker","direccion-de-fotografia","edicion"]},{"slug":"y-el-ano-que-viene-que","servicios":["direccion-de-fotografia","filmmaker","edicion"]}]$datos$::jsonb as j)
insert into public.proyecto_servicios (proyecto_id, servicio_id, orden)
select pr.id, s.id, x.n
from d, jsonb_array_elements(d.j) p
join public.proyectos pr on pr.idioma = 'es' and pr.slug = p ->> 'slug' and pr.estado = 'borrador'
cross join lateral jsonb_array_elements_text(p -> 'servicios') with ordinality x(slug, n)
join public.servicios s on s.idioma = 'es' and s.slug = x.slug
on conflict do nothing;

-- 4. Artículos
with d as (select $datos$[{"slug":"el-arte-de-contar-historias-con-luz","id_antiguo":"el-arte-de-contar-historias-con-luz","titulo":"Dirección de fotografía: el arte de contar historias con luz","fecha":"2024-07-15","extracto":"La luz es el pincel del director de fotografía. Cómo un esquema de luz cambia lo que sentimos.","categoria":"Dirección de fotografía","contenido":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cuando empiezo un proyecto, lo primero que me pregunto no es qué cámara voy a usar. Me pregunto qué quiero que sienta quien mira. La luz es la forma más directa que tengo de decidirlo: un cambio pequeño en su dirección o en su calidad puede convertir un espacio acogedor en uno amenazante, o a un personaje en alguien en quien confiar o de quien desconfiar."}]},{"type":"paragraph","content":[{"type":"text","text":"Me obsesiona la luz natural. Me fijo en cómo cae a distintas horas, en la suavidad de la hora mágica, en cómo se cuela por una persiana. Pero no siempre se puede depender de ella, y ahí empieza el oficio: recrearla, o inventar otra, con difusores, reflectores y una posición muy cuidada."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cuando la luz sale de la mente"}]},{"type":"paragraph","content":[{"type":"text","text":"En "},{"type":"text","text":"El Cirujano","marks":[{"type":"italic"}]},{"type":"text","text":" quise que la luz no tuviera una fuente lógica. En las escenas del asesino no hay lámparas ni ventanas que lo justifiquen: la luz sale de su cabeza, y por eso es un rojo abrasador. Todo lo demás, la investigación, es frío y analítico. Ese choque es la historia."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cuando el color cuenta el tiempo"}]},{"type":"paragraph","content":[{"type":"text","text":"En el EP "},{"type":"text","text":"Oscuridad","marks":[{"type":"italic"}]},{"type":"text","text":" usé el color como reloj. Empezamos la primera canción a todo color y, tema a tema, fuimos desaturando la imagen hasta acabar en blanco y negro. Nadie dice que la relación se está rompiendo; se ve."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cuando la luz protege"}]},{"type":"paragraph","content":[{"type":"text","text":"En "},{"type":"text","text":"No se está tan mal","marks":[{"type":"italic"}]},{"type":"text","text":" la luz tenía que ser un refugio. En lugar de iluminar plano, esculpí el espacio con destellos, contraluces y reflejos en cristal y agua, para que el artista estuviera dentro de una burbuja donde pudiera mostrarse sin miedo."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cuando no tienes nada"}]},{"type":"paragraph","content":[{"type":"text","text":"En mis recreaciones aprendí lo que más me gusta del oficio. Para la ventana de Vito Corleone usé la rejilla de una estufa de butano, cinta negra y papel de horno. Con eso y una luz bien colocada, un sótano se convierte en un despacho de "},{"type":"text","text":"El Padrino","marks":[{"type":"italic"}]},{"type":"text","text":". La luz no necesita presupuesto; necesita intención."}]},{"type":"paragraph","content":[{"type":"text","text":"Cada proyecto es un lienzo distinto, y la luz es siempre mi herramienta principal para contar la historia."}]}]},"imagen":"https://www.platinocrowdfunding.com/storage/project/5454/img/eO2uv54rRAQy1AgsNjm0ybjXLN92jg4mkW9zFxZR.png"},{"slug":"ia-artesano-audiovisual","id_antiguo":"ia-artesano-audiovisual","titulo":"El artesano y la inteligencia artificial en el cine","fecha":"2025-05-13","extracto":"Qué cambia la IA en la producción audiovisual y por qué el trabajo artesano sigue importando.","categoria":"Oficio","contenido":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"El mundo audiovisual ha sido, hasta ahora, un trabajo artesano. Pero ¿dónde queda nuestra huella cuando una IA puede imitar en segundos un estilo que tardamos años en construir?"}]},{"type":"paragraph","content":[{"type":"text","text":"Esa es la gran duda. En nuestro oficio, la mano, el gusto y la experiencia van puliendo una voz propia. Y aunque una inteligencia artificial pueda replicar una estética, difícilmente tendrá esa \"alma\" o esa riqueza de matices que surgen de la vivencia humana."}]},{"type":"paragraph","content":[{"type":"text","text":"Esta semana he estado dándole muchas vueltas y creo que merece la pena pararse a pensarlo."}]},{"type":"paragraph","content":[{"type":"text","text":"A muchos compañeros, e incluso a mí mismo, nos genera cierto rechazo ver obras generadas al 100 % por IA. A menudo se sienten vacías y, de alguna manera, invasoras. Sin embargo, creo que ese rechazo viene de mirar desde el ángulo equivocado, y de dejar de lado su verdadero potencial."}]},{"type":"paragraph","content":[{"type":"text","text":"La clave está en no ver a la IA como la \"creadora\". Hay que verla como el mejor asistente posible."}]},{"type":"paragraph","content":[{"type":"text","text":"Es una herramienta poderosísima para ejecutar ideas que antes eran imposibles sin presupuestos desorbitados. Y la clave está en integrarla en el flujo de trabajo para potenciarnos a nosotros, no para sustituirnos."}]},{"type":"paragraph","content":[{"type":"text","text":"Estamos viendo pasos gigantes en el buen camino. Me gusta mucho el enfoque de Runway: herramientas que buscan darnos control total sobre lo que hacemos, en lugar de dejarlo todo al azar. Su potencial, para mí, está en poder modificar el propio material que hemos grabado: incluir público en un estadio, añadir efectos visuales muy costosos o matizar la iluminación si en rodaje no ha quedado como esperábamos. Lo mismo con lo que se pudo ver la semana pasada en Adobe Max: la integración de la IA generativa directamente en nuestros timelines."}]},{"type":"paragraph","content":[{"type":"text","text":"En conclusión, creo que la tecnología cambia y avanza, pero somos nosotros quienes tenemos que construir el camino, haciendo un uso responsable e inteligente de ella. La inteligencia artificial no va a reemplazar al artesano, pero el artesano que sepa usar estas nuevas herramientas tendrá un taller mucho más potente para materializar su visión."}]}]},"imagen":"https://i.ibb.co/KxmsqgfX/Captura-de-pantalla-2026-05-13-154839.png"}]$datos$::jsonb as j)
insert into public.articulos as t (idioma, slug, id_antiguo, titulo, fecha, extracto, contenido, categoria_id, imagen_id, estado)
select 'es', a ->> 'slug', a ->> 'id_antiguo', a ->> 'titulo', (a ->> 'fecha')::date, a ->> 'extracto', a -> 'contenido',
  (select id from public.categorias_articulo where idioma = 'es' and nombre = a ->> 'categoria'),
  (select id from public.medios where url_origen = a ->> 'imagen' order by creado_en limit 1),
  'borrador'
from d, jsonb_array_elements(d.j) a
on conflict (idioma, slug) do update set
  id_antiguo = excluded.id_antiguo, titulo = excluded.titulo, fecha = excluded.fecha, extracto = excluded.extracto,
  contenido = excluded.contenido, categoria_id = excluded.categoria_id, imagen_id = excluded.imagen_id
where t.estado = 'borrador';

-- 5. Recuento
select
  (select count(*) from public.medios) as medios,
  (select count(*) from public.proyectos) as proyectos,
  (select count(*) from public.proyecto_servicios) as servicios_enlazados,
  (select count(*) from public.articulos) as articulos;
